// .../reco/+/+ -> Routenkarten + Detailansicht aller Routen.
// Für jede Route: die Daten der Karte (Empfehlung, Kurzbegründung, Vergleich, Abfahrt)
// und die komplette Detailansicht als HTML. Das Template-Widget zeigt alle Karten;
// ein Klick auf eine Karte öffnet darunter die Details (Auswahl merkt sich jeder Browser).
const cfg = global.get('cfg');
let recos = context.get('recos');
if (!recos || recos.__prefix !== cfg.prefix) recos = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty || typeof msg.payload !== 'object') delete recos[key];
else recos[key] = msg.payload;
context.set('recos', recos);

// Texte aus MQTT-Nachrichten immer maskieren (öffentlicher Broker!)
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g,
    c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const time = ts => ts ? new Date(ts).toLocaleTimeString('de-DE',
    { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' }) : '–';
const icon = { bike: '🚲', transit: '🚌', walk: '🚶' };
const row = (k, v) => '<tr><td>' + k + '</td><td>' + v + '</td></tr>';

function render(r) {
    const f = r.facts || {};
    const best = r.options.find(o => o.mode === r.best) || { why: [] };
    let h = '';
    // --- Empfehlung
    h += '<div class="mm-hero mm-' + r.best + '"><div class="mm-hero-icon">' + icon[r.best] + '</div><div>' +
        '<div class="mm-hero-label">Empfehlung für „' + esc(r.name) + '“</div>' +
        '<div class="mm-hero-title">' + esc(r.bestLabel) + ' · ' + r.bestMin + ' min</div>' +
        '<div class="mm-hero-why">' + esc(r.reason || best.why.join(' · ')) + '</div></div></div>';
    h += '<div class="mm-route">' + esc(f.fromAddress) + ' → ' + esc(f.toAddress) + '</div>';

    // --- Vergleich der Optionen
    h += '<div class="mm-h">Vergleich</div><div class="mm-cards">';
    for (const o of r.options) {
        h += '<div class="mm-card' + (o.mode === r.best ? ' mm-best' : '') + (o.ok ? '' : ' mm-off') + '">' +
            '<div class="mm-card-top"><span>' + icon[o.mode] + ' ' + esc(o.label) + '</span><b>' +
            (o.ok ? o.min + ' min' : 'nicht möglich') + '</b></div><ul>' +
            o.why.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul></div>';
    }
    h += '</div>';

    // --- Strecke
    const fs = f.fromStation || {}, ts = f.toStation || {}, b = f.bike;
    h += '<div class="mm-h">Strecke</div><table class="mm-table">';
    h += row('Start', esc(f.fromAddress));
    h += row('Station am Start', esc(fs.name) + ' <span class="mm-dim">(' + fs.distM + ' m, ca. ' + Math.round(fs.walkMin) + ' min zu Fuß)</span>');
    if (b && !f.sameStation) {
        h += row('Radstrecke', b.km + ' km · ' + Math.round(b.min) + ' min Fahrt <span class="mm-dim">(Station → Station)</span>');
        h += row('Höhenmeter', b.ascent != null ? '↑ ' + Math.round(b.ascent) + ' m · ↓ ' + Math.round(b.descent) + ' m' : '<span class="mm-dim">unbekannt (ohne ORS)</span>');
        h += row('Radweganteil', b.cyclewayPct != null ? b.cyclewayPct + ' %' : '<span class="mm-dim">unbekannt (ohne ORS)</span>');
        h += row('Steile Abschnitte (ab 7 %)', b.steepPct != null ? b.steepPct + ' % der Strecke' : '<span class="mm-dim">unbekannt (ohne ORS)</span>');
    } else {
        h += row('Radstrecke', '<span class="mm-dim">entfällt (Start und Ziel an derselben Station)</span>');
    }
    h += row('Station am Ziel', esc(ts.name) + ' <span class="mm-dim">(' + ts.distM + ' m, ca. ' + Math.round(ts.walkMin) + ' min zu Fuß)</span>');
    h += row('Ziel', esc(f.toAddress));
    h += row('Abfahrt', r.departure ? esc(r.departure.text) + (r.nextDepartureText ? ' <span class="mm-dim">(nächste: ' + esc(r.nextDepartureText) + ')</span>' : '') : '<span class="mm-dim">keine Abfahrtszeit</span>');
    h += row('Fußweg komplett', f.walk.km + ' km · ' + Math.round(f.walk.min) + ' min');
    h += row('ÖPNV', Math.round(f.transit.min) + ' min <span class="mm-dim">(Schätzung)</span>');
    h += '</table>';

    // --- Live-Lage
    const w = f.weather;
    h += '<div class="mm-h">Live-Lage</div><table class="mm-table">';
    h += row('Räder an ' + esc(fs.name), fs.bikes != null ? '<b>' + fs.bikes + '</b> von ' + fs.capacity + ' <span class="mm-dim">(Stand ' + time(fs.ts) + ')</span>' : '<span class="mm-dim">keine Daten</span>');
    h += row('Freie Plätze an ' + esc(ts.name), ts.docks != null ? '<b>' + ts.docks + '</b> von ' + ts.capacity + ' <span class="mm-dim">(Stand ' + time(ts.ts) + ')</span>' : '<span class="mm-dim">keine Daten</span>');
    h += row('Wetter', w && w.ok ? w.temp + ' °C · ' + w.precip + ' mm Regen · ' + w.wind + ' km/h Wind <span class="mm-dim">(Stand ' + time(w.ts) + (w.demo ? ', Simulation' : '') + ')</span>' : '<span class="mm-dim">keine aktuellen Daten</span>');
    const srcCls = s => String(s).indexOf('online') === 0 ? 'mm-ok' : 'mm-bad';
    h += row('Datenquellen', 'BiciMAD: <span class="' + srcCls(f.sources.bicimad) + '">' + esc(f.sources.bicimad) + '</span> · Wetter: <span class="' + srcCls(f.sources.weather) + '">' + esc(f.sources.weather) + '</span> · Profil: ' + esc(f.sources.profile));
    h += '</table>';

    if (r.notes && r.notes.length) h += '<div class="mm-notes">ℹ ' + r.notes.map(esc).join('<br>ℹ ') + '</div>';
    h += '<div class="mm-foot">Stand: ' + time(Date.parse(r.updated)) + ' · Nutzer: ' + esc(r.user) + '</div>';
    return h;
}

const routes = Object.keys(recos).filter(k => k !== '__prefix').sort().map(k => {
    const r = recos[k];
    const bike = r.options.find(o => o.mode === 'bike') || {};
    return {
        key: k, label: r.user + ' – ' + r.name, user: r.user, name: r.name,
        from: r.from, to: r.to,
        best: r.best, bestLabel: r.bestLabel, bestMin: r.bestMin, icon: icon[r.best],
        reason: r.reason || '',
        options: r.options.map(o => ({ mode: o.mode, label: o.label.replace(' (Schätzung)', ''), icon: icon[o.mode],
            min: o.min, ok: o.ok, estimated: !!o.estimated })),
        knapp: !!bike.knapp,
        departureText: r.departure ? r.departure.text : null,
        nextDeparture: r.nextDeparture || null,
        nextDepartureText: r.nextDepartureText || null,
        hint: (r.notes || []).find(n => /fehlen|ohne Wetter/.test(n)) || null,
        demo: !!(r.facts && r.facts.weather && r.facts.weather.demo),
        windowMin: cfg.reco.windowMin,
        html: render(r)
    };
});
return { payload: { routes: routes } };

// .../reco/+/+ -> Tabelle aller Empfehlungen (eine Zeile pro Route)
const cfg = global.get('cfg');
let rows = context.get('rows');
if (!rows || rows.__prefix !== cfg.prefix) rows = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty || typeof msg.payload !== 'object') {
    delete rows[key];
} else {
    const r = msg.payload;
    const o = m => r.options.find(x => x.mode === m);
    const fmt = x => !x ? '–' : (x.ok ? x.min + ' min' : 'nicht möglich');
    const best = o(r.best);
    rows[key] = {
        'Nutzer': r.user,
        'Route': r.name,
        'Von → Nach': r.from + ' → ' + r.to,
        'Empfehlung': r.bestLabel + ' (' + r.bestMin + ' min)',
        'BiciMAD': fmt(o('bike')),
        'ÖPNV*': fmt(o('transit')),
        'Zu Fuß': fmt(o('walk')),
        'Begründung': (best ? best.why : []).concat(r.notes || []).join(', '),
        'Stand': new Date(r.updated).toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid' })
    };
}
context.set('rows', rows);
msg.payload = Object.keys(rows).filter(k => k !== '__prefix').map(k => rows[k]).sort((a, b) =>
    (a['Nutzer'] + a['Route']).localeCompare(b['Nutzer'] + b['Route']));
return msg;

// .../alerts/<nutzer> -> Popup im Dashboard
const user = msg.topic.split('/').pop();
return { payload: user + ': ' + msg.payload };

// Formular "Route anlegen / löschen". Jedes Eingabefeld sendet mit eigenem msg.topic.
// Start und Ziel kommen aus den Auswahllisten (feste Orte + Suchtreffer, siehe "Ortsliste bauen").
// Ausgang 1: MQTT (Route anlegen / löschen) | 2: Statustext
const cfg = global.get('cfg');
const P = cfg.prefix;
const f = flow.get('form') || { time: '08:30', days: [1, 2, 3, 4, 5] };
const slug = s => String(s || '').toLowerCase().normalize('NFD')
    .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '').slice(0, 30);
const save = () => flow.set('form', f);

switch (msg.topic) {
    case 'user': f.user = msg.payload; break;
    case 'name': f.name = msg.payload; break;
    case 'from': f.from = msg.payload; break;
    case 'to': f.to = msg.payload; break;
    case 'time': f.time = msg.payload; break;
    case 'days': f.days = (Array.isArray(msg.payload) ? msg.payload : [msg.payload]).map(Number).filter(Boolean); break;
    case 'delSel': f.del = msg.payload; break;
    case 'create': {
        const u = slug(f.user), r = slug(f.name);
        const idx = flow.get('placeIndex') || {};
        const a = idx[f.from], b = idx[f.to];
        if (!u || !r) return [null, { payload: '⚠ Bitte deinen Namen und einen Routennamen eingeben.' }];
        if (!a || !b) return [null, { payload: '⚠ Bitte Start und Ziel auswählen (Ort aus der Liste oder vorher eine Adresse suchen).' }];
        if (f.from === f.to) return [null, { payload: '⚠ Start und Ziel sind gleich.' }];
        if (!/^\d{1,2}:\d{2}$/.test(String(f.time || ''))) return [null, { payload: '⚠ Bitte eine Abfahrtszeit eingeben (z. B. 08:30).' }];
        if (!f.days || !f.days.length) return [null, { payload: '⚠ Bitte mindestens einen Wochentag wählen.' }];
        const existing = Object.keys(flow.get('routeKeys') || {});
        const mine = existing.filter(k => k.split('/')[0] === u && k !== u + '/' + r);
        if (mine.length >= cfg.reco.maxRoutesPerUser) {
            return [null, { payload: '⚠ Höchstens ' + cfg.reco.maxRoutesPerUser + ' Routen pro Nutzer.' }];
        }
        save();
        const time = f.time.padStart(5, '0');
        const days = f.days.slice().sort();
        const route = {
            name: f.name,
            from: { label: a.label, lat: a.lat, lon: a.lon },
            to: { label: b.label, lat: b.lat, lon: b.lon },
            departure: { time: time, days: days },
            createdAt: new Date().toISOString()
        };
        return [
            { topic: P + '/routes/' + u + '/' + r, payload: route, qos: 1, retain: true },
            { payload: '✔ Route ' + u + '/' + r + ' angelegt: ' + a.label + ' → ' + b.label + ', Abfahrt ' + time +
                '. Aufs Handy: ' + P + '/alerts/' + u }
        ];
    }
    case 'delete': {
        if (!f.del) return [null, { payload: '⚠ Bitte eine Route zum Löschen wählen.' }];
        const key = f.del;
        f.del = null;
        save();
        // Leere Retained-Nachricht = gespeicherte Nachricht auf dem Broker löschen
        return [
            { topic: P + '/routes/' + key, payload: '', qos: 1, retain: true },
            { payload: '🗑 Route ' + key + ' gelöscht.' }
        ];
    }
}
save();
return null;

// Adresssuche auf Knopfdruck (Nominatim / OpenStreetMap), begrenzt auf Madrid.
// Bis zu 5 Treffer, aus denen der Nutzer in der Auswahlliste den richtigen wählt.
// Ausgang 1: Anfrage an Nominatim | 2: Statustext
const cfg = global.get('cfg');
if (msg.topic === 'query') { flow.set('searchText', msg.payload); return null; }
let q = String(flow.get('searchText') || '').trim();
if (q.length < 3) return [null, { payload: '⚠ Bitte mindestens 3 Zeichen eingeben.' }];
if (!/madrid/i.test(q)) q += ', Madrid';
const url = cfg.apis.geocode + '?format=jsonv2&limit=5&countrycodes=es&bounded=1' +
    '&viewbox=' + cfg.cityViewbox + '&q=' + encodeURIComponent(q);
return [{
    query: q,
    url: url,
    headers: { 'User-Agent': cfg.apis.geocodeUserAgent, 'Accept-Language': 'es' }
}, { payload: '🔎 Suche „' + q + '“ …' }];

// Wertet die Nominatim-Antwort aus: bis zu 5 Treffer kommen oben in die Auswahllisten
// für Start und Ziel (markiert mit 🔎). Der Nutzer sieht so, was gefunden wurde.
// Ausgang 1: an "Ortsliste bauen" | 2: Statustext
const list = msg.statusCode === 200 && Array.isArray(msg.payload) ? msg.payload : null;
if (!list) {
    node.status({ fill: 'red', shape: 'ring', text: 'Fehler HTTP ' + msg.statusCode });
    return [null, { payload: '⚠ Fehler bei der Suche (HTTP ' + msg.statusCode + '). Bitte einen festen Ort wählen.' }];
}
if (!list.length) {
    return [null, { payload: '⚠ Nichts gefunden für „' + msg.query + '“. Genauer angeben, z. B. „Calle de Alcalá 50“.' }];
}
const stamp = Date.now().toString(36);
const hits = list.slice(0, 5).map((h, i) => {
    // Kurzer Name: die ersten zwei bis drei Teile der Adresse
    const parts = String(h.display_name || '').split(',').map(s => s.trim());
    // "50, Calle de Alcalá, ..." -> "Calle de Alcalá 50"
    const short = /^\d+[a-zA-Z]?$/.test(parts[0]) ? parts[1] + ' ' + parts[0] : parts[0];
    const area = parts.find(p => /^(Centro|Salamanca|Chamberí|Retiro|Arganzuela|Moncloa|Chamartín|Tetuán|Latina|Carabanchel|Usera|Puente de Vallecas|Villa de Vallecas|Ciudad Lineal|Hortaleza|Fuencarral|Moratalaz|San Blas|Barajas|Vicálvaro|Villaverde)/.test(p));
    return { value: 'geo:' + stamp + '-' + i, label: short + (area && short.indexOf(area) < 0 ? ' (' + area + ')' : (parts[1] && short.indexOf(parts[1]) < 0 ? ', ' + parts[1] : '')),
        lat: Number(h.lat), lon: Number(h.lon) };
});
node.status({ fill: 'green', shape: 'dot', text: hits.length + ' Treffer' });
return [{ topic: 'hits', payload: hits },
    { payload: '✔ ' + hits.length + (hits.length === 1 ? ' Treffer' : ' Treffer') + ' für „' + msg.query +
        '“. Sie stehen jetzt ganz oben in den Listen Start und Ziel (🔎).' }];

// .../routes/+/+ -> Liste aller Routen (für "Route löschen" und die Obergrenze)
const cfg = global.get('cfg');
let routes = flow.get('routeKeys');
if (!routes || routes.__prefix !== cfg.prefix) routes = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete routes[key];
else if (typeof msg.payload === 'object') routes[key] = msg.payload.name || key;
flow.set('routeKeys', routes);
const options = Object.keys(routes).filter(k => k !== '__prefix').sort().map(k => ({ label: k + ' – ' + routes[k], value: k }));
return { ui_update: { options: options.length ? options : [{ label: '(keine Routen)', value: '' }] } };

// .../system/+ -> Tabelle "Datenquellen"
const cfg = global.get('cfg');
let rows = context.get('rows');
if (!rows || rows.__prefix !== cfg.prefix) rows = { __prefix: cfg.prefix };
const name = msg.topic.split('/').pop();
rows[name] = {
    'Quelle': name,
    'Status': String(msg.payload),
    'Seit': new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid' })
};
context.set('rows', rows);
return { payload: Object.keys(rows).filter(k => k !== '__prefix').map(k => rows[k]) };

// .../live/weather -> Textzeile
const w = msg.payload;
if (typeof w !== 'object' || w == null) return null;
const t = new Date(w.ts).toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid' });
return { payload: w.temp + ' °C · ' + w.precip + ' mm Regen · ' + w.wind + ' km/h Wind · ' + t + (w.demo ? ' (Simulation)' : '') };

// Demo und Simulation (Seite "System & Demo").
// - Demo-Routen: drei Routen für den Nutzer "demo", Abfahrt in 14 min (also sofort "aktiv")
// - Szenarien: Kommando an den Simulator über .../sim/cmd (QoS 1, nicht retained).
//   Der Simulator ist ein eigener Dienst (Tab "Simulation"); das Dashboard kennt ihn nur über MQTT.
const cfg = global.get('cfg');
const P = cfg.prefix;
if (typeof msg.topic === 'string' && msg.topic.indexOf('sim:') === 0) {
    return [[{ topic: P + '/sim/cmd', payload: { scenario: msg.topic.slice(4), by: 'dashboard' }, qos: 1, retain: false }]];
}
if (msg.topic === 'demoroutes') {
    // Abfahrt = jetzt + 14 min (Uhrzeit in Madrid), jeden Tag
    const parts = {};
    new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false })
        .formatToParts(new Date(Date.now() + 14 * 60000)).forEach(p => { parts[p.type] = p.value; });
    const time = String(Number(parts.hour) % 24).padStart(2, '0') + ':' + parts.minute;
    const pl = id => (cfg.places || []).find(p => p.id === id);
    const pt = id => { const p = pl(id); return { label: p.label, lat: p.lat, lon: p.lon }; };
    const mk = (id, name, a, b) => ({
        topic: P + '/routes/demo/' + id, qos: 1, retain: true,
        payload: { name: name, from: pt(a), to: pt(b), departure: { time: time, days: [1, 2, 3, 4, 5, 6, 7] },
            createdAt: new Date().toISOString() }
    });
    return [[
        mk('sol-moncloa', 'Sol → Moncloa', 'sol', 'moncloa'),
        mk('atocha-retiro', 'Atocha → Retiro', 'atocha', 'retiro'),
        mk('moncloa-uni', 'Moncloa → Ciudad Universitaria', 'moncloa', 'ciudad-uni')
    ]];
}
return null;

// Baut die Auswahllisten für Start und Ziel:
//   🔎 Suchtreffer der letzten Adresssuche (oben)
//   feste Orte aus .../static/places (retained), nach Kategorie sortiert
// Die Listen sind "Comboboxen": man kann tippen, um zu filtern.
// placeIndex merkt sich zu jedem Eintrag Name und Koordinaten (für das Formular).
const cfg = global.get('cfg');
if (msg.topic === 'hits') {
    flow.set('hits', msg.payload);
} else if (typeof msg.topic === 'string' && msg.topic.endsWith('/static/places')) {
    flow.set('places', Array.isArray(msg.payload) ? msg.payload : []);
}
const hits = flow.get('hits') || [];
const places = flow.get('places') || [];
const order = { Uni: 1, Bahnhof: 2, Zentrum: 3 };
const index = {};
const options = [];
for (const h of hits) {
    index[h.value] = { label: h.label, lat: h.lat, lon: h.lon };
    options.push({ label: '🔎 ' + h.label, value: h.value });
}
places.slice().sort((a, b) => (order[a.cat] || 9) - (order[b.cat] || 9) || a.label.localeCompare(b.label, 'es'))
    .forEach(p => {
        const v = 'place:' + p.id;
        index[v] = { label: p.label, lat: p.lat, lon: p.lon };
        options.push({ label: p.label + ' · ' + p.cat, value: v });
    });
flow.set('placeIndex', index);
node.status({ fill: 'green', shape: 'dot', text: places.length + ' Orte, ' + hits.length + ' Suchtreffer' });
return { ui_update: { options: options.length ? options : [{ label: '(lädt …)', value: '' }] } };

// Beim Start: Vorgaben ins Formular schreiben (Abfahrt 08:30, Mo–Fr)
const f = flow.get('form') || {};
f.time = f.time || '08:30';
f.days = (f.days && f.days.length) ? f.days : [1, 2, 3, 4, 5];
flow.set('form', f);
return [{ payload: f.time }, { payload: f.days }];

// .../sim/state (retained) -> Textzeile auf der Seite "System & Demo"
const s = msg.payload;
if (!s || typeof s !== 'object' || !s.active) return { payload: 'Keine Simulation aktiv: es laufen echte Daten.' };
const since = new Date(s.startedAt).toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit' });
return { payload: '▶ ' + s.label + ' (seit ' + since + ')' + (s.phase ? ' · ' + s.phase : '') +
    (s.stations ? ' · ' + s.stations + ' Stationen simuliert' : '') };
